-fn to_mixed(r: Rat) -> str {
-    ""
+fn to_mixed(r: Rat) -> str {    if r.num == 0 {
+        return "0"
+    }
+    let neg = r.num < 0
+    let n = abs_i64(r.num)
+    let whole = n / r.den
+    let rem = n % r.den
+    let sign = if neg { "-" } else { "" }
+    if rem == 0 {
+        return sign + to_str(whole)
+    }
+    if whole == 0 {
+        return sign + to_str(rem) + "/" + to_str(r.den)
+    }
+    sign + to_str(whole) + " " + to_str(rem) + "/" + to_str(r.den)
 }

